ALTER TABLE public.products ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS image_note text;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS technical_sheet_url text;
WITH assets(code,description,image_url,image_note,technical_sheet_url) AS (VALUES
('PAINT-001','أساس أكريليك مائي للداخل والخارج. يقاوم القلوية ويمتاز بقوة الالتصاق وسرعة الجفاف على الخرسانة واللياسة والجبس والطوب.','https://v.high-star.iq/paints/images/star-primer.png','الصورة من صفحة ستار برايمر. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/11901-star-primer.pdf'),
('PAINT-002','أساس أكريليك نقي للداخل والخارج، بمقاومة للقلوية والتصاق قوي. يُستخدم أيضاً ضمن أنظمة حماية الخرسانة وفي المناطق المعرضة للرطوبة.','https://v.high-star.iq/paints/images/pura-primer.png','الصورة من صفحة بيورا برايمر. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/18111-pura-primer.pdf'),
('PAINT-003','دهان أكريليك مطفي للجدران والسقوف الداخلية، بتشطيب ناعم وتغطية جيدة وقابلية للغسل.','https://v.high-star.iq/paints/images/flex-series.jpg','صورة مشتركة لسلسلة فلكس. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/17210-flex-interior.pdf'),
('PAINT-004','دهان أكريليك مطفي للواجهات، ويمكن استخدامه داخلياً أيضاً. يعطي سطحاً ناعماً وتغطية عالية ويقاوم العوامل الجوية.','https://v.high-star.iq/paints/images/flex-series.jpg','صورة مشتركة لسلسلة فلكس. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/17310-flex-exterior.pdf'),
('PAINT-005','دهان أكريليك مطفي للداخل والخارج. يمتاز بتغطية عالية وقابلية للغسل واحتفاظ جيد باللون.','https://v.high-star.iq/paints/images/star-series.jpg','صورة مشتركة لسلسلة ستار. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/19310-star-super-plus.pdf'),
('PAINT-006','دهان أكريليك نقي للواجهات، بتشطيب مطفي ناعم. يقاوم العوامل الجوية ويمتاز بقابلية الغسل وثبات اللون.','https://v.high-star.iq/paints/images/star-series.jpg','صورة مشتركة لسلسلة ستار. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/19330-star-guard.pdf'),
('PAINT-007','دهان أكريليك داخلي مطفي، بتغطية عالية والتصاق قوي وقابلية للغسل. مناسب للخرسانة واللياسة والجبس والطوب.','https://v.high-star.iq/paints/images/star-series.jpg','صورة مشتركة لسلسلة ستار. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/19210-star-matt.pdf'),
('PAINT-008','دهان داخلي بتشطيب مطفي ناعم جداً، قابل للغسل ويحافظ على اللون. منخفض المركبات العضوية المتطايرة.','https://v.high-star.iq/paints/images/pura-series.jpg','صورة مشتركة لسلسلة بيورا. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/18210-pura-matt.pdf'),
('PAINT-009','بيورا جارد مطفي هو الإصدار الخارجي المطابق للوصف. دهان أكريليك نقي للواجهات، قابل للغسل ويقاوم التقاط الغبار، ويُستخدم أيضاً داخلياً.','https://v.high-star.iq/paints/images/pura-series.jpg','صورة مشتركة لسلسلة بيورا. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/18320-pura-guard-matt.pdf'),
('PAINT-010','دهان أكريليك داخلي نصف لامع، بملمس ناعم وتغطية عالية وقابلية للغسل. منخفض المركبات العضوية المتطايرة.','https://v.high-star.iq/paints/images/pura-series.jpg','صورة مشتركة لسلسلة بيورا. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/18510-pura-semi-gloss.pdf'),
('PAINT-011','معجون جاهز لسد الثقوب والشقوق وتسوية العيوب داخلياً وخارجياً. سهل الفرد والصنفرة ويصلح لأسطح منها الخرسانة واللياسة والجبس والخشب.
العبوة الصغيرة منشورة بوزن 3 كغم. تسمية كالون غير مؤكدة لهذا المنتج.','https://v.high-star.iq/paints/images/filler-series.jpg','صورة مشتركة لسلسلة فيلر. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/12401-all-purpose-filler.pdf'),
('PAINT-012','عبوة 20 كغم من معجون التصليح الجاهز نفسه. يصلح لتسوية العيوب في الأسطح الجديدة أو المطلية سابقاً.','https://v.high-star.iq/paints/images/filler-series.jpg','صورة مشتركة لسلسلة فيلر. المقاس غير ظاهر على الصورة.','https://v.high-star.iq/paints/product-sheets/12401-all-purpose-filler.pdf'),
('PAINT-013','طلاء ستايرين أكريليك للأسطح الخرسانية الخارجية. يسد المسام ويغطي الشقوق الشعرية ويقاوم الماء والرطوبة والأشعة فوق البنفسجية. تذكر الشركة أنه يعكس حرارة الشمس.','https://v.high-star.iq/paints/images/bbc-generic-pack.jpg','صورة عبوة BBC عامة من الموقع. تتكرر لمنتجات مختلفة.','https://v.high-star.iq/paints/product-sheets/11811-roof-guard-plus.pdf'),
('PAINT-014','أساس زيتي أحادي المكوّن للحديد داخلياً وخارجياً. يلتصق بالصلب الإنشائي والأنابيب والسقالات ويقاوم التآكل. مخصص للصلب غير المجلفن.
النشرة تطابق اسم «سلقون». اللون الزنجاري غير محدد في النشرة.','https://v.high-star.iq/paints/images/bbc-generic-pack.jpg','صورة عبوة BBC عامة من الموقع. تتكرر لمنتجات مختلفة.','https://v.high-star.iq/paints/product-sheets/21123-metal-primer.pdf'),
('PAINT-015','دهان نهائي زيتي لامع للداخل والخارج، للخشب والمعادن والخرسانة بعد التهيئة المناسبة. يمتاز بانسيابية جيدة واحتفاظ باللمعة.','https://v.high-star.iq/paints/images/bbc-generic-pack.jpg','صورة عبوة BBC عامة من الموقع. تتكرر لمنتجات مختلفة.','https://v.high-star.iq/paints/product-sheets/22620-veneer-gloss.pdf'),
('PAINT-016','طلاء براتنج السيليكون للمعادن المعرضة للحرارة، مثل الأنابيب والعوادم. تذكر النشرة أن المعالجة تبدأ عند 200°م وأن مقاومة الحرارة تصل إلى 650°م.','https://v.high-star.iq/paints/images/bbc-generic-pack.jpg','صورة عبوة BBC عامة من الموقع. تتكرر لمنتجات مختلفة.','https://v.high-star.iq/paints/product-sheets/81980-heat-resistant-aluminum.pdf')
)
UPDATE public.products p SET description=a.description,image_url=a.image_url,image_note=a.image_note,technical_sheet_url=a.technical_sheet_url
FROM assets a WHERE p.code=a.code AND p.category='أصباغ';
NOTIFY pgrst,'reload schema';
